  "docs.fees.f4": "Agitar la caja de otro",
  "docs.fees.f4.price": "2,5 USDC",
  "docs.fees.f4.to": "El 70 % para quien tiene la caja, el 30 % para la tesorería",
  "docs.fees.f5": "Créditos de descifrado, más allá de los gratuitos",
